191	+// How the feature tables name the rows of each account table: accounts by local reference,
192	+// space memberships as account@space.
193	+const visibleAccountTableRows = async (
194	+  client: ReturnType<typeof getServiceClient>,
195	+  table: string,
196	+): Promise<string[]> => {
197	+  const localRefs = (world.localRefs || {}) as LocalRefsType;
198	+  const names = new Map(
199	+    Object.entries(localRefs).map(([name, id]) => [id, name]),
200	+  );
201	+  const nameOf = (id: number | null): string =>
202	+    id === null ? "none" : (names.get(id) ?? `id ${id}`);
203	+  let rows: string[];
204	+  if (table === "PlatformAccount") {
205	+    const response = await client.from("PlatformAccount").select("id");
206	+    assert.equal(response.error, null, table);
207	+    rows = response.data!.map(({ id }) => nameOf(id));
208	+  } else if (table === "AgentIdentifier") {
209	+    const response = await client.from("AgentIdentifier").select("account_id");
210	+    assert.equal(response.error, null, table);
211	+    rows = response.data!.map(({ account_id }) => nameOf(account_id));
212	+  } else if (table === "LocalAccess") {
213	+    const response = await client
214	+      .from("LocalAccess")
215	+      .select("account_id, space_id");
216	+    assert.equal(response.error, null, table);
217	+    rows = response.data!.map(
218	+      ({ account_id, space_id }) => `${nameOf(account_id)}@${nameOf(space_id)}`,
219	+    );
220	+  } else assert.fail(`unknown table ${table}`);
221	+  return rows.sort();
222	+};
223	+
224	+Then(
225	+  "a user logged in space {word} should see these account table rows:",
226	+  async (viewerSpaceName: string, table: DataTable) => {
227	+    const { client } = await getSpaceClient(viewerSpaceName);
228	+    for (const { table: tableName, rows } of table.hashes()) {
229	+      const expected = rows!
230	+        .split(",")
231	+        .map((name) => name.trim())
232	+        .filter((name) => name !== "")
233	+        .sort();
234	+      assert.deepEqual(
235	+        await visibleAccountTableRows(client, tableName!),
236	+        expected,
237	+        tableName,
238	+      );
239	+    }
240	+  },
241	+);
242	+
243	+// Same approach as the account write results. An update flips the identifier's trusted flag.
244	+Then(
245	+  "a user logged in space {word} should get these identifier write results:",
246	+  async (writerSpaceName: string, table: DataTable) => {
247	+    const localRefs = (world.localRefs || {}) as LocalRefsType;
248	+    const { client } = await getSpaceClient(writerSpaceName);
249	+    const service = getServiceClient();
250	+    const mismatches: string[] = [];
251	+    for (const { operation, account, result } of table.hashes()) {
252	+      const label = `${operation} identifier of ${account}`;
253	+      const accountId = localRefs[account!];
254	+      if (typeof accountId !== "number") assert.fail(`unknown ${account}`);
255	+      const before = await service
256	+        .from("AgentIdentifier")
257	+        .select("*")
258	+        .eq("account_id", accountId);
259	+      assert.equal(before.error, null, label);
260	+      const existing = before.data!;
261	+      let written: boolean;
262	+      if (operation === "insert") {
263	+        const value = `new-${account}@example.com`;
264	+        await client.from("AgentIdentifier").insert({
265	+          account_id: accountId,
266	+          value,
267	+          identifier_type: "email",
268	+          trusted: false,
269	+        });
270	+        const undone = await service
271	+          .from("AgentIdentifier")
272	+          .delete()
273	+          .eq("account_id", accountId)
274	+          .eq("value", value)
275	+          .select("value");
276	+        assert.equal(undone.error, null, label);
277	+        written = (undone.data?.length ?? 0) > 0;
278	+      } else if (operation === "update") {
279	+        if (existing.length === 0) assert.fail(`${label}: no identifier`);
280	+        const trusted = !existing[0]!.trusted;
281	+        await client
282	+          .from("AgentIdentifier")
283	+          .update({ trusted })
284	+          .eq("account_id", accountId);
285	+        const after = await service
286	+          .from("AgentIdentifier")
287	+          .select("trusted")
288	+          .eq("account_id", accountId);
289	+        assert.equal(after.error, null, label);
290	+        written = after.data!.some((row) => row.trusted === trusted);
291	+        const undone = await service.from("AgentIdentifier").upsert(existing);
292	+        assert.equal(undone.error, null, label);
293	+      } else if (operation === "delete") {
294	+        if (existing.length === 0) assert.fail(`${label}: no identifier`);
295	+        await client
296	+          .from("AgentIdentifier")
297	+          .delete()
298	+          .eq("account_id", accountId);
299	+        const after = await service
300	+          .from("AgentIdentifier")
301	+          .select("value")
302	+          .eq("account_id", accountId);
303	+        assert.equal(after.error, null, label);
304	+        written = after.data!.length === 0;
305	+        const undone = await service
306	+          .from("AgentIdentifier")
307	+          .upsert(existing, { ignoreDuplicates: true });
308	+        assert.equal(undone.error, null, label);
309	+      } else assert.fail(`unknown operation ${operation}`);
310	+      if (result !== "allowed" && result !== "denied")
311	+        assert.fail(`unknown result ${result} for ${label}`);
312	+      if (written !== (result === "allowed"))
313	+        mismatches.push(`${label}: expected ${result}`);
314	+    }
315	+    assert.deepEqual(mismatches, []);
316	+  },
317	+);
