418	@@ -0,0 +1,108 @@
419	+-- The account policies check access once per query: the helpers take no row column, so (SELECT ...) runs each once.
420	+-- Spaces the caller can read or edit are checked per row against LocalAccess, through its primary key, so single-account checks stay cheap.
421	+-- Inside a policy, LocalAccess is filtered by its own reader-level select policy. PlatformAccount reads start at partial access, so they go through a definer view the planner can inline, and writes to LocalAccess and AgentIdentifier go through account_ids_in_shared_spaces.
422	+-- What the policies allow does not change.
423	+
424	+-- The planner can't inline this function, and its default estimate of 1000 rows makes it scan SpaceAccess instead of using the primary key.
425	+-- The caller plus their groups is usually a few rows. Measured on generated data: above 10, plans get worse as SpaceAccess grows.
426	+ALTER FUNCTION public.my_user_accounts() ROWS 10;
427	+
428	+CREATE OR REPLACE FUNCTION public.my_platform_account_ids() RETURNS SETOF BIGINT
429	+STABLE SECURITY DEFINER
430	+SET search_path = ''
431	+LANGUAGE sql
432	+AS $$
433	+    SELECT id FROM public."PlatformAccount" WHERE dg_account = auth.uid();
434	+$$;
435	+
436	+COMMENT ON FUNCTION public.my_platform_account_ids IS 'security utility: the platform accounts I own. Takes no row column, so a policy runs it once per query.';
437	+
438	+REVOKE ALL ON FUNCTION public.my_platform_account_ids() FROM public, anon;
439	+GRANT EXECUTE ON FUNCTION public.my_platform_account_ids() TO authenticated, service_role;
440	+
441	+CREATE OR REPLACE FUNCTION public.account_ids_in_shared_spaces(access_level public."SpaceAccessPermissions" = 'reader')
442	+RETURNS TABLE (account_id BIGINT, unowned BOOLEAN)
443	+STABLE SECURITY DEFINER
444	+SET search_path = ''
445	+LANGUAGE sql AS $$
446	+    SELECT DISTINCT la.account_id, pa.dg_account IS NULL
447	+    FROM public."SpaceAccess" AS sa
448	+    JOIN public.my_user_accounts() AS my (uid) ON (sa.account_uid = my.uid)
449	+    JOIN public."LocalAccess" AS la USING (space_id)
450	+    JOIN public."PlatformAccount" AS pa ON (pa.id = la.account_id)
451	+    WHERE sa.permissions >= access_level;
452	+$$;
453	+
454	+COMMENT ON FUNCTION public.account_ids_in_shared_spaces IS 'security utility: the accounts in spaces where I have at least this access level, and whether each is unowned. Takes no row column, so a policy runs it once per query.';
455	+
456	+REVOKE ALL ON FUNCTION public.account_ids_in_shared_spaces(public."SpaceAccessPermissions") FROM public, anon;
457	+GRANT EXECUTE ON FUNCTION public.account_ids_in_shared_spaces(public."SpaceAccessPermissions") TO authenticated, service_role;
458	+
459	+-- Definer view on purpose: inside a policy, LocalAccess is filtered by its own reader-level select policy, so an inline check can't see partial access.
460	+-- Unlike a function, the planner can inline a view, so a policy can check one account without building the whole set.
461	+-- Keep DISTINCT and don't add space_id: LocalAccess only shows memberships at reader level, and one row per membership would reveal them.
462	+CREATE OR REPLACE VIEW public.accounts_in_my_partial_spaces AS
463	+SELECT DISTINCT la.account_id
464	+FROM public."SpaceAccess" AS sa
465	+    JOIN public.my_user_accounts() AS my (uid) ON (sa.account_uid = my.uid)
466	+    JOIN public."LocalAccess" AS la USING (space_id)
467	+WHERE sa.permissions >= 'partial';
468	+
469	+COMMENT ON VIEW public.accounts_in_my_partial_spaces IS 'security utility: the accounts in spaces where I have at least partial access. Used by the PlatformAccount select policy.';
470	+
471	+REVOKE ALL ON public.accounts_in_my_partial_spaces FROM public, anon, authenticated, service_role;
472	+GRANT SELECT ON public.accounts_in_my_partial_spaces TO authenticated, service_role;
473	+
474	+-- Account policies
475	+
476	+DROP POLICY IF EXISTS platform_account_select_policy ON public."PlatformAccount";
477	+CREATE POLICY platform_account_select_policy ON public."PlatformAccount" FOR SELECT USING (dg_account = (SELECT auth.uid() LIMIT 1) OR EXISTS (SELECT 1 FROM public.accounts_in_my_partial_spaces AS v WHERE v.account_id = "PlatformAccount".id));
478	+
479	+DROP POLICY IF EXISTS platform_account_delete_policy ON public."PlatformAccount";
480	+CREATE POLICY platform_account_delete_policy ON public."PlatformAccount" FOR DELETE USING (dg_account = (SELECT auth.uid() LIMIT 1) OR (dg_account IS null AND EXISTS (SELECT 1 FROM public."LocalAccess" AS la WHERE la.account_id = "PlatformAccount".id AND la.space_id = any((SELECT public.my_space_ids('editor'))::bigint[]))));
481	+
482	+DROP POLICY IF EXISTS platform_account_insert_policy ON public."PlatformAccount";
