grant all on sp, ac to authenticated;
do $$ declare t text; i bigint; begin
 foreach t in array array['none','dpartial','dreader','deditor','gpartial','greader','geditor','mix'] loop
  insert into public."Space"(url,name,platform) values ('http://'||t,t,'Roam') returning id into i;
  insert into sp values (t,i);
 end loop;
end $$;
insert into public."SpaceAccess"(account_uid,space_id,permissions)
 select case when tag like 'd%' then '00000000-0000-4000-8000-0000000000a1'::uuid else '00000000-0000-4000-8000-0000000000a3'::uuid end, id,
        (case when tag like '%partial' then 'partial' when tag like '%reader' then 'reader' else 'editor' end)::public."SpaceAccessPermissions"
 from sp where tag not in ('none','mix');
-- mix: partial direct, editor through the group
insert into public."SpaceAccess"(account_uid,space_id,permissions) select '00000000-0000-4000-8000-0000000000a1',id,'partial' from sp where tag='mix';
insert into public."SpaceAccess"(account_uid,space_id,permissions) select '00000000-0000-4000-8000-0000000000a3',id,'editor' from sp where tag='mix';
-- someone else's grants, which must not count
insert into public."SpaceAccess"(account_uid,space_id,permissions) select '00000000-0000-4000-8000-0000000000a2',id,'editor' from sp where tag='none';
do $$ declare s record; o text; i bigint; n text; begin
 for s in select * from sp loop
  foreach o in array array['u','m','o'] loop
   n := s.tag||'_'||o;
   insert into public."PlatformAccount"(name,platform,account_local_id,dg_account) values (n,'Roam',n,
     case o when 'm' then '00000000-0000-4000-8000-0000000000a1'::uuid when 'o' then '00000000-0000-4000-8000-0000000000a2'::uuid end) returning id into i;
   insert into ac values (n,i);
   insert into public."LocalAccess"(account_id,space_id) values (i,s.id);
  end loop;
 end loop;
 foreach o in array array['u','m','o'] loop
   -- no membership at all
   n := 'nola_'||o;
   insert into public."PlatformAccount"(name,platform,account_local_id,dg_account) values (n,'Roam',n,
     case o when 'm' then '00000000-0000-4000-8000-0000000000a1'::uuid when 'o' then '00000000-0000-4000-8000-0000000000a2'::uuid end) returning id into i;
   insert into ac values (n,i);
   -- two memberships: partial+reader, partial+partial
   n := 'pr_'||o;
   insert into public."PlatformAccount"(name,platform,account_local_id,dg_account) values (n,'Roam',n,
     case o when 'm' then '00000000-0000-4000-8000-0000000000a1'::uuid when 'o' then '00000000-0000-4000-8000-0000000000a2'::uuid end) returning id into i;
   insert into ac values (n,i);
   insert into public."LocalAccess"(account_id,space_id) select i,id from sp where tag in ('dpartial','dreader');
   n := 'pe_'||o;
   insert into public."PlatformAccount"(name,platform,account_local_id,dg_account) values (n,'Roam',n,
     case o when 'm' then '00000000-0000-4000-8000-0000000000a1'::uuid when 'o' then '00000000-0000-4000-8000-0000000000a2'::uuid end) returning id into i;
   insert into ac values (n,i);
   insert into public."LocalAccess"(account_id,space_id) select i,id from sp where tag in ('gpartial','none');
 end loop;
end $$;
insert into public."AgentIdentifier"(identifier_type,account_id,value,trusted) select 'email',id,tag||'@x',false from ac;
-- sql bodies below reference objects replaced later
set check_function_bodies=off;
create function pg_temp.login() returns void language plpgsql as $f$ begin
 perform set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-0000000000a1","role":"authenticated"}',true);
 perform set_config('request.jwt.claim.sub','00000000-0000-4000-8000-0000000000a1',true);
 set local role authenticated;
end $f$;
create function pg_temp.try(mode text, label text, stmt text, pre text default null) returns void language plpgsql as $f$
declare n bigint; res text; begin
 begin
  if pre is not null then execute pre; end if;
  perform pg_temp.login();
  execute stmt; get diagnostics n = row_count;
  res := n::text;
  raise exception 'probe_undo';
 exception when others then
  if sqlerrm <> 'probe_undo' then res := 'ERR '||sqlstate; end if;
 end;
 reset role;
 insert into probe_res values (mode,label,res);
end $f$;
create function pg_temp.run_probes(mode text) returns void language plpgsql as $f$
declare a record; b record; s record; begin
 for a in select * from ac loop
  perform pg_temp.try(mode,'PA select '||a.tag,format('select 1 from public."PlatformAccount" where id=%s',a.id));
  perform pg_temp.try(mode,'AI select '||a.tag,format('select 1 from public."AgentIdentifier" where account_id=%s',a.id));
  perform pg_temp.try(mode,'LA select '||a.tag,format('select 1 from public."LocalAccess" where account_id=%s',a.id));
  perform pg_temp.try(mode,'PA update '||a.tag,format('update public."PlatformAccount" set name=name||''x'' where id=%s',a.id));
  perform pg_temp.try(mode,'PA delete '||a.tag,format('delete from public."PlatformAccount" where id=%s',a.id),format('delete from public."AgentIdentifier" where account_id=%s',a.id));
  perform pg_temp.try(mode,'AI update '||a.tag,format('update public."AgentIdentifier" set trusted=true where account_id=%s',a.id));
  perform pg_temp.try(mode,'AI delete '||a.tag,format('delete from public."AgentIdentifier" where account_id=%s',a.id));
  perform pg_temp.try(mode,'AI insert '||a.tag,format('insert into public."AgentIdentifier"(identifier_type,account_id,value,trusted) values (''email'',%s,''new'',false)',a.id));
  perform pg_temp.try(mode,'LA delete '||a.tag,format('delete from public."LocalAccess" where account_id=%s',a.id));
  perform pg_temp.try(mode,'generic '||a.tag,format('select 1 where public.generic_entity_access(%s,''PlatformAccount'')',a.id));
  for s in select * from sp loop
   perform pg_temp.try(mode,'LA insert '||a.tag||' in '||s.tag,format('insert into public."LocalAccess"(account_id,space_id) values (%s,%s)',a.id,s.id));
   perform pg_temp.try(mode,'LA update space '||a.tag||' to '||s.tag,format('update public."LocalAccess" set space_id=%s where account_id=%s',s.id,a.id));
  end loop;
  for b in select * from ac where tag in ('none_u','deditor_u','dpartial_u','deditor_m','deditor_o','nola_m','mix_u') loop
   perform pg_temp.try(mode,'LA update acct '||a.tag||' to '||b.tag,format('update public."LocalAccess" set account_id=%s where account_id=%s',b.id,a.id));
   perform pg_temp.try(mode,'AI update acct '||a.tag||' to '||b.tag,format('update public."AgentIdentifier" set account_id=%s where account_id=%s',b.id,a.id));
  end loop;
 end loop;
 perform pg_temp.try(mode,'PA full count','select 1 from public."PlatformAccount"');
 perform pg_temp.try(mode,'AI full count','select 1 from public."AgentIdentifier"');
 perform pg_temp.try(mode,'LA full count','select 1 from public."LocalAccess"');
 perform pg_temp.try(mode,'PA insert unowned','insert into public."PlatformAccount"(name,platform,account_local_id) values (''z'',''Roam'',''z'')');
end $f$;

select pg_temp.run_probes('new');
\echo === view rows per account as caller, vs LocalAccess visible
select pg_temp.login();
create temp table vc as select a.tag, (select count(*) from public.accounts_in_my_partial_spaces v where v.account_id=a.id) vrows, (select count(*) from public."LocalAccess" l where l.account_id=a.id) la_vis, (select count(*) from public."PlatformAccount" p where p.id=a.id) pa_vis from ac a;
select * from vc where tag in ('pr_o','pe_o','dpartial_o','dreader_o','nola_o','none_o') order by 1;
\echo === view ids the caller cannot see in PlatformAccount (must be empty)
select v.account_id from public.accounts_in_my_partial_spaces v where not exists (select 1 from public."PlatformAccount" p where p.id=v.account_id);
reset role;

CREATE OR REPLACE FUNCTION public.is_my_account(account_id BIGINT) RETURNS boolean
STABLE SECURITY DEFINER
SET search_path = ''
LANGUAGE sql
AS $$
    SELECT EXISTS (
        SELECT 1 FROM public."PlatformAccount"
        WHERE id = account_id AND dg_account = auth.uid()
        LIMIT 1
    );
$$;
CREATE OR REPLACE FUNCTION public.account_in_shared_space(p_account_id BIGINT, access_level public."SpaceAccessPermissions" = 'reader') RETURNS boolean
STABLE SECURITY DEFINER
SET search_path = ''
LANGUAGE sql AS $$
    SELECT EXISTS (
      SELECT 1
      FROM public."LocalAccess" AS la
      JOIN public."SpaceAccess" AS sa USING (space_id)
      JOIN public.my_user_accounts() ON (sa.account_uid = my_user_accounts)
      WHERE la.account_id = p_account_id
      AND sa.permissions >= access_level
    );
$$;
CREATE OR REPLACE FUNCTION public.unowned_account_in_shared_space(p_account_id BIGINT, access_level public."SpaceAccessPermissions" = 'reader') RETURNS boolean
STABLE SECURITY DEFINER
SET search_path = ''
LANGUAGE sql AS $$
    SELECT EXISTS (
        SELECT 1
        FROM public."SpaceAccess" AS sa
        JOIN public.my_user_accounts() ON (sa.account_uid = my_user_accounts)
        JOIN public."LocalAccess" AS la USING (space_id)
        JOIN public."PlatformAccount" AS pa ON (pa.id=la.account_id)
        WHERE la.account_id = p_account_id
          AND pa.dg_account IS NULL
          AND sa.permissions >= access_level
    );
$$;
CREATE OR REPLACE FUNCTION public.generic_entity_access(target_id BIGINT, target_type public."EntityType") RETURNS boolean
STABLE SECURITY DEFINER
SET search_path = ''
LANGUAGE sql AS $$
    SELECT CASE
        WHEN target_type = 'Space' THEN public.in_space(target_id, 'editor')
        WHEN target_type = 'Content' THEN public.content_in_space(target_id, 'editor')
        WHEN target_type = 'Concept' THEN public.concept_in_space(target_id, 'editor')
        WHEN target_type = 'Document' THEN public.document_in_space(target_id, 'editor')
        WHEN target_type = 'PlatformAccount' THEN public.account_in_shared_space(target_id, 'editor')
        ELSE false
    END;
$$;
DROP POLICY IF EXISTS platform_account_select_policy ON public."PlatformAccount";
DROP POLICY IF EXISTS platform_account_delete_policy ON public."PlatformAccount";
DROP POLICY IF EXISTS platform_account_insert_policy ON public."PlatformAccount";
DROP POLICY IF EXISTS platform_account_update_policy ON public."PlatformAccount";
DROP POLICY IF EXISTS local_access_select_policy ON public."LocalAccess";
DROP POLICY IF EXISTS local_access_delete_policy ON public."LocalAccess";
DROP POLICY IF EXISTS local_access_insert_policy ON public."LocalAccess";
DROP POLICY IF EXISTS local_access_update_policy ON public."LocalAccess";
DROP POLICY IF EXISTS agent_identifier_select_policy ON public."AgentIdentifier";
DROP POLICY IF EXISTS agent_identifier_delete_policy ON public."AgentIdentifier";
DROP POLICY IF EXISTS agent_identifier_insert_policy ON public."AgentIdentifier";
DROP POLICY IF EXISTS agent_identifier_update_policy ON public."AgentIdentifier";
CREATE POLICY platform_account_select_policy ON public."PlatformAccount" FOR SELECT USING (dg_account = (SELECT auth.uid() LIMIT 1) OR public.account_in_shared_space(id, 'partial'));
CREATE POLICY platform_account_delete_policy ON public."PlatformAccount" FOR DELETE USING (dg_account = (SELECT auth.uid() LIMIT 1) OR (dg_account IS null AND public.unowned_account_in_shared_space(id, 'editor')));
CREATE POLICY platform_account_insert_policy ON public."PlatformAccount" FOR INSERT WITH CHECK (dg_account = (SELECT auth.uid() LIMIT 1) OR (dg_account IS null AND public.unowned_account_in_shared_space(id, 'editor')));
CREATE POLICY platform_account_update_policy ON public."PlatformAccount" FOR UPDATE USING (dg_account = (SELECT auth.uid() LIMIT 1) OR (dg_account IS null AND public.unowned_account_in_shared_space(id, 'editor')));
CREATE POLICY local_access_select_policy ON public."LocalAccess" FOR SELECT USING (space_id = any((SELECT public.my_space_ids('reader'))::bigint []));
CREATE POLICY local_access_delete_policy ON public."LocalAccess" FOR DELETE USING (space_id = any((SELECT public.my_space_ids('editor'))::bigint[]) AND (public.unowned_account_in_shared_space(account_id, 'editor') OR public.is_my_account(account_id)));
CREATE POLICY local_access_insert_policy ON public."LocalAccess" FOR INSERT WITH CHECK (space_id = any((SELECT public.my_space_ids('editor'))::bigint[]) AND (public.unowned_account_in_shared_space(account_id, 'editor') OR public.is_my_account(account_id)));
CREATE POLICY local_access_update_policy ON public."LocalAccess" FOR UPDATE USING (space_id = any((SELECT public.my_space_ids('editor'))::bigint[]) AND (public.unowned_account_in_shared_space(account_id, 'editor') OR public.is_my_account(account_id)));
CREATE POLICY agent_identifier_select_policy ON public."AgentIdentifier" FOR SELECT USING (public.account_in_shared_space(account_id));
CREATE POLICY agent_identifier_delete_policy ON public."AgentIdentifier" FOR DELETE USING (public.unowned_account_in_shared_space(account_id, 'editor') OR public.is_my_account(account_id));
CREATE POLICY agent_identifier_insert_policy ON public."AgentIdentifier" FOR INSERT WITH CHECK (public.unowned_account_in_shared_space(account_id, 'editor') OR public.is_my_account(account_id));
CREATE POLICY agent_identifier_update_policy ON public."AgentIdentifier" FOR UPDATE USING (public.unowned_account_in_shared_space(account_id, 'editor') OR public.is_my_account(account_id));
select pg_temp.run_probes('old');
\echo === probe totals
select mode, count(*), count(*) filter (where n like 'ERR%') errs, count(*) filter (where n='0') zero, count(*) filter (where n not like 'ERR%' and n<>'0') nonzero from probe_res group by 1;
\echo === distinct errors per probe kind in new
select split_part(probe,' ',1)||' '||split_part(probe,' ',2) k, n, count(*) from probe_res where mode='new' group by 1,2 order by 1,2;
\echo === differences old vs new
select o.probe, o.n as old, nw.n as new from probe_res o full join probe_res nw on o.probe=nw.probe and nw.mode='new' where o.mode='old' and o.n is distinct from nw.n order by 1 limit 60;
select count(*) as diff_count from probe_res o join probe_res nw on o.probe=nw.probe and nw.mode='new' where o.mode='old' and o.n is distinct from nw.n;

